    for a,label,purpose,start,end,loop,duration,point in ACTIONS:
        acting=c['points'][point]
        prompt=f"Animate {c['name']} ({id}) using the approved individual sheet and neutral base image. Explicit Animal Crossing-like rounded matte 3D toy/game look. Action: {EN[a]}. Acting direction: {acting}. Anatomy locked: {c['identity']}. Same outfit colors, wrap, eye/face location, scale and one left-hip potion throughout. Fixed 30-degree downward orthographic game camera, no zoom, pan, cuts, text, other characters, festival scenery or portal. Full body and feet remain visible inside an unchanged square canvas. Root XY is fixed. Duration {duration:.1f}s at 24fps. {'Seamless repeat, same first and last pose and effect phase.' if loop else 'One shot with controlled start and end pose.'} Start: {start}. End: {end}. Prefer genuine alpha; if unsupported use a single flat color that is absent from this character's palette. Keep ground shadow in a separate output. No gore, no realistic fur texture, no extra anatomy."
        row={'character':id,'name_ko':c['name'],'action':a,'purpose':purpose,'start_pose':start,'end_pose':end,'loop':loop,'recommended_seconds':duration,'acting':acting,'prompt':prompt,'file':f'{id}_{a}_v01.webm'};rows.append(row)
        blocks += [f"## {label}\n",f"- 목적: {purpose}\n- 시작: {start}\n- 끝: {end}\n- 반복: {'예' if loop else '아니오'}\n- 권장 길이: {duration:.1f}초\n- 연기 포인트: {acting}\n- 파일: `{id}_{a}_v01.webm` / `{id}_{a}_v01_preview.mp4`\n",f"### 생성용 프롬프트\n\n{prompt}\n"]
